function validate([edges]) {
  const n = edges.length + 1;
  if (n < 3 || n > 100000) return 'A star needs 3 to 10^5 nodes, so 2 to 10^5 - 1 edges.';
  const degree = new Array(n + 1).fill(0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n) return 'Node labels must be between 1 and n = edges.length + 1.';
    if (u === v) return 'An edge cannot connect a node to itself.';
    degree[u]++;
    degree[v]++;
  }
  let hubs = 0;
  for (let node = 1; node <= n; node++) {
    if (degree[node] === n - 1) hubs++;
    else if (degree[node] !== 1) return 'The edges must form a star: one center joined to every other node.';
  }
  if (hubs !== 1) return 'The edges must form a star: one center joined to every other node.';
  return null;
}

