function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 502) : 3 + Math.floor(rand() * 6);
  const center = 1 + Math.floor(rand() * n);
  const edges = [];
  for (let node = 1; node <= n; node++) {
    if (node !== center) edges.push(rand() < 0.5 ? [center, node] : [node, center]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  return [edges];
}
